"""Reusable, transparent question-pattern variation for student *practice* vivas.

These are thirty prompt styles, not externally generated AI questions.  All prompts
are grounded in the teacher's topic and request the learner to reason only from
course material.  No grades or fake facts are generated by these templates.
"""
from __future__ import annotations

from hashlib import blake2b
from random import Random

# Three phrasings per reasoning style. Each style is used at most once in a
# 30-question practice session. Templates are safe for arbitrary subjects.
PATTERNS: tuple[tuple[str, tuple[str, str, str]], ...] = (
    ('Definition', ('Define {topic} in your own words, using the course meaning.', 'What does {topic} mean? Give a precise explanation.', 'Give a clear definition of {topic} from your course.')),
    ('Main idea', ('What is the central idea behind {topic}?', 'Explain the most important principle of {topic}.', 'Summarize the core rule or principle associated with {topic}.')),
    ('Example', ('Give an example that demonstrates {topic}, and explain the connection.', 'Illustrate {topic} with one suitable example from your studies.', 'Describe an example of {topic} and why it fits.')),
    ('Procedure', ('Explain the process or steps involved in {topic}, if applicable.', 'Walk through how {topic} works, in a logical order.', 'Break down the mechanism or procedure behind {topic}.')),
    ('Reasoning', ('Why does {topic} work the way it does?', 'Explain the reasoning that supports {topic}.', 'What is the justification for the main rule in {topic}?')),
    ('Prerequisites', ('What prior concepts must someone understand before learning {topic}?', 'Identify an important prerequisite for {topic} and explain why it matters.', 'What background knowledge helps make sense of {topic}?')),
    ('Comparison', ('Compare {topic} with a related concept covered in your course.', 'How does {topic} differ from a related approach or idea?', 'Identify one meaningful similarity and one difference involving {topic}.')),
    ('Application', ('How could {topic} be applied to a suitable problem?', 'Describe a practical use of {topic}, using only your course knowledge.', 'What kind of problem could be solved using {topic}?')),
    ('Scenario', ('Imagine a new situation in which {topic} is relevant. How would you approach it?', 'Create a simple scenario involving {topic} and explain your reasoning.', 'Explain how you would recognize when to apply {topic} in a scenario.')),
    ('Evidence', ('What evidence or course explanation supports the key claim about {topic}?', 'How could you justify an explanation of {topic} using course material?', 'What information would you cite to support the main idea of {topic}?')),
    ('Misconception', ('Describe a common misunderstanding about {topic} and correct it.', 'What mistake might a beginner make when learning {topic}? Explain the correction.', 'Identify a misconception about {topic} and explain why it is wrong.')),
    ('Limitation', ('What is a limitation or condition of {topic}, if discussed in the course?', 'When might {topic} not apply? Explain any course-supported limits.', 'Explain an important constraint or limitation involving {topic}.')),
    ('Assumptions', ('What assumptions are required when reasoning about {topic}?', 'Identify the conditions under which the rule for {topic} is valid.', 'What must be true before you can apply {topic} correctly?')),
    ('Troubleshooting', ('If an application of {topic} gives an unexpected result, what should you check?', 'How would you investigate a misunderstanding or error involving {topic}?', 'Describe how you would find and correct a mistake in using {topic}.')),
    ('Teach-back', ('Teach {topic} to a new student in simple terms.', 'How would you explain {topic} to a classmate who is learning it for the first time?', 'Introduce {topic} to a beginner without using unnecessary jargon.')),
    ('Analogy', ('Can you explain {topic} with a suitable analogy and its limitations?', 'Give a real-life analogy for {topic}; state where it stops being accurate.', 'Illustrate {topic} with an analogy and connect it to the actual concept.')),
    ('Connection', ('How does {topic} relate to another idea in this course?', 'What other concept in the course is closely connected to {topic}, and why?', 'Explain one connection between {topic} and an already learned concept.')),
    ('Why important', ('Why is {topic} important in this subject?', 'What would be harder to understand or do without {topic}?', 'Explain the significance of {topic} within your course.')),
    ('Interpretation', ('Interpret a key statement or rule about {topic} in your own words.', 'Explain what a typical course statement about {topic} really means.', 'Translate the main explanation of {topic} into simpler language.')),
    ('Trade-off', ('If there are alternative approaches, what trade-off is associated with {topic}?', 'Describe any advantages and disadvantages of {topic} compared with another approach.', 'Discuss an appropriate trade-off when choosing {topic}.')),
    ('Conditions', ('How do you decide whether {topic} applies to a particular problem?', 'Which conditions would make {topic} appropriate to use?', 'What clues tell you that {topic} is the right concept for a question?')),
    ('Counterexample', ('Can you give an example where a common overgeneralization about {topic} fails?', 'Explain a case that shows why a rule about {topic} needs its conditions.', 'Describe a counterexample to a mistaken claim involving {topic}.')),
    ('Accuracy', ('How would you check whether an explanation of {topic} is correct?', 'What criteria would you use to verify a claim about {topic}?', 'Explain how to test understanding of {topic} against course material.')),
    ('Cause and effect', ('What causes or influences the outcome related to {topic}?', 'Explain an important cause-and-effect relationship in {topic}.', 'How does changing a relevant condition affect the use of {topic}?')),
    ('Breakdown', ('Divide {topic} into its main parts or components.', 'What elements make up {topic} and how do they interact?', 'Explain the major components involved in {topic}.')),
    ('Decision', ('How would you decide between {topic} and a related idea?', 'What questions would you ask before choosing to apply {topic}?', 'Describe a reasoned choice involving the use of {topic}.')),
    ('Reformulation', ('Restate {topic} as a short question and answer it.', 'Explain {topic} from a different perspective while keeping its meaning.', 'Rephrase the main concept of {topic} without changing the facts.')),
    ('Review', ('What are the three most important points to remember about {topic}?', 'Give a concise revision summary of {topic}.', 'Which key facts about {topic} would you put on a study card?')),
    ('Question design', ('Write a challenging viva question about {topic}, then explain its expected answer.', 'What would you ask another student to check their understanding of {topic}? Answer it.', 'Design a brief assessment question about {topic} and justify the answer.')),
    ('Synthesis', ('Bring together the key definition, example, and limitation of {topic}.', 'Give a complete but concise explanation of {topic} using a rule and an example.', 'Summarize {topic}, including how it works and when it is relevant.')),
)
assert len(PATTERNS) == 30


def prompt_for_turn(session_id: int, student_id: int, course_id: int, turn: int, topic_name: str) -> tuple[str, str]:
    """Return a stable (style, prompt) for session/turn; never leak answers."""
    seed = int.from_bytes(blake2b(f'{session_id}:{student_id}:{course_id}'.encode(), digest_size=8).digest(), 'big')
    rng = Random(seed)
    order = list(range(len(PATTERNS)))
    rng.shuffle(order)
    style_index = order[turn % len(order)]
    name, versions = PATTERNS[style_index]
    # Full cycles (only 30 allowed currently) are deliberately distinct.
    variant = (rng.randrange(len(versions)) + turn // len(order)) % len(versions)
    return name, versions[variant].format(topic=topic_name)
